return {
    -- CaptorCooke [8298]
    ["STR_ID_CaptorCooke[8298][Text1]"] = "No criminal can escape from my hands! Here`s a letter for the DC Vice Captain. I need you to head to the Desert and deliver this letter to him.",
    ["STR_ID_CaptorCooke[8298][Text2]"] = "Thank you for all you have done. Your name will be remembered by us!",
    ["STR_ID_CaptorCooke[8298][Text3]"] = "Listen, this maybe a little complicated. Take these two Corpse Bags and these two Smell Bags of the two snake races. Use them in the appointed place to entice the elders of the 2 races from their lair and kill them. After the elders are killed!",
    ["STR_ID_CaptorCooke[8298][Text4]"] = "@STR_COMMON[14]",
    ["STR_ID_CaptorCooke[8298][Text5]"] = "@STR_COMMON[26]",
    ["STR_ID_CaptorCooke[8298][Text6]"] = "My scout reported that the two snake races are at war! Thank you for your help! Now we can deliver the final blow!",
    ["STR_ID_CaptorCooke[8298][Text7]"] = "Now, carry these 2 Smell Bags and slay 40 Snakemen and 40 Heresy Snakemen. The smell of the other race will be left on the dead body of the Snakemen and Heresy Snakemen. Let`s make their hatred greater!",
    ["STR_ID_CaptorCooke[8298][Text8]"] = "@STR_COMMON[14]",
    ["STR_ID_CaptorCooke[8298][Text9]"] = "It is great to have you help me! Now, listen carefully to my plan!",
    ["STR_ID_CaptorCooke[8298][Text10]"] = "Slay 20 Snakemen and 20 Heresy Snakemen and use these 2 Smell bags to collect their smell.",
    ["STR_ID_CaptorCooke[8298][Text11]"] = "The Snakeman and the Heresy Snakeman are two major snake races in Ape City. I have a secret plan to stir up a fight between them! Take these 2 Smell Bags, and go slay 20 Snakemen and 20 Heresy Snakemen to collect their smell.",
    ["STR_ID_CaptorCooke[8298][Text12]"] = "@STR_COMMON[14]",
    ["STR_ID_CaptorCooke[8298][Text13]"] = "Good job! This plan will not succeed without your help! Here are your rewards!",
    ["STR_ID_CaptorCooke[8298][Text14]"] = "@STR_COMMON[14]",
    ["STR_ID_CaptorCooke[8298][Text15]"] = "The Snakeman and the Heresy Snakeman are the two major creatures, here. They usually stir up trouble for us, but I have a plan to pick up a fight between them. Go speak with Harmony Taoist to learn more about the plan!",
    ["STR_ID_CaptorCooke[8298][Text16]"] = "Wonderful! With the help of the Cloud Riding, I can bring the criminal back to Ape City and have him punished by law safely! Here are your rewards!",
    ["STR_ID_CaptorCooke[8298][Text17]"] = "@STR_COMMON[14]",
    ["STR_ID_CaptorCooke[8298][Text18]"] = "I heard that there is a famous Harmony Taoist here. He must know a shortcut to the Ape City. Go ask him for me! You know, I need to stay here watch this criminal.",
    ["STR_ID_CaptorCooke[8298][Text19]"] = "It is all cliff around here. I need to return to the Ape City as soon as possible! What can I do?",
    ["STR_ID_CaptorCooke[8298][Text20]"] = "Can you find a shortcut for me? I need to stay here watch this criminal.",
    ["STR_ID_CaptorCooke[8298][Text21]"] = "I just captured a wanted criminal! But I am afraid that his friends will come to rescue him. I need to return to Ape City as fast as possible! Can you find a shortcut for me? I need to stay here and watch this ruffian!",
    ["STR_ID_CaptorCooke[8298][Option1]"] = "Quest:~Back~Home(1).",
